import { describe, expect, it } from 'vitest';
import {
  addMyTrackFallbackGates,
  buildMyTrackGates,
  classifyMyTrackObstacles,
  evaluateMyTrackCentreline,
  fitMyTrackCentreline,
  myTrackBodyFramePoints,
} from '../mission/labAlgorithms';
import fixture from './fixtures/my_track_conformance.json';

// Conformance fixture generated by running the REAL Python implementation
// (kart/kart_sim/my_track_algorithm.py's body_frame_points/classify_obstacles/
// build_gates/add_single_side_fallback_gates/fit_centreline/evaluate_centreline)
// on a fixed set of tracked cones + kart pose -- see
// /tmp (regenerate via the generator script referenced in the developer's
// final report if the layout or AlgorithmConfig values change).
//
// Tolerance: gate/point counts must match EXACTLY (they are discrete
// classification decisions driven by the same width/skew/link thresholds
// ported verbatim into labAlgorithms.ts -- any mismatch is a real behavioural
// difference, not numerical noise). Centreline y-values are allowed 1e-3 m
// of slack: numpy.polyfit uses a QR-based least-squares solve while the TS
// port uses Gaussian elimination on the normal equations -- same maths,
// different floating-point path, and this fixture's geometry is exactly
// symmetric (y should land at ~0 either way) so 1e-3 m is generous, not a
// hidden tolerance for a real discrepancy.
const TOLERANCE_M = 1e-3;

describe('MY_TRACK TS-vs-Python conformance', () => {
  const cones = (fixture.tracks as Array<{ x_m: number; y_m: number; colour: string; track_id: number }>).map((t) => ({
    id: String(t.track_id), x_m: t.x_m, y_m: t.y_m, class: t.colour.toUpperCase().replace('LARGE_ORANGE', 'ORANGE'), confidence: 1,
  }));
  const pose = { x_m: fixture.pose[0], y_m: fixture.pose[1], yaw_rad: fixture.pose[2] };

  it('matches body-frame windowing, obstacle classification and gate counts', () => {
    const points = myTrackBodyFramePoints(cones, pose);
    expect(points.length).toBe(fixture.num_body_points);

    const obstacleIndices = classifyMyTrackObstacles(points, new Set());
    expect(obstacleIndices.size).toBe(fixture.num_obstacle_indices);

    const boundaryIndices = points.map((_, i) => i).filter((i) => !obstacleIndices.has(i));
    const boundary = boundaryIndices.map((i) => points[i]);
    expect(boundary.length).toBe(fixture.num_boundary_points);

    const realGates = buildMyTrackGates(boundary);
    expect(realGates.length).toBe(fixture.num_real_gates);

    const fallbackGates = addMyTrackFallbackGates(boundary, realGates);
    expect(fallbackGates.length).toBe(fixture.num_fallback_gates);
  });

  it('matches the fitted centreline within 1e-3 m at the fixture sample points', () => {
    const points = myTrackBodyFramePoints(cones, pose);
    const obstacleIndices = classifyMyTrackObstacles(points, new Set());
    const boundary = points.filter((_, i) => !obstacleIndices.has(i));
    const realGates = buildMyTrackGates(boundary);
    const fallbackGates = addMyTrackFallbackGates(boundary, realGates);
    const fit = fitMyTrackCentreline([...realGates, ...fallbackGates])!;
    expect(fit).not.toBeNull();
    fixture.sample_xs.forEach((x, i) => {
      const y = evaluateMyTrackCentreline(fit, x);
      expect(Math.abs(y - fixture.sample_ys[i])).toBeLessThanOrEqual(TOLERANCE_M);
    });
  });
});
